create table public.service_packages(service_id text references public.services(id),tier text check(tier in ('advanced','vip')),price_fils integer not null check(price_fils>0),primary key(service_id,tier)); alter table public.service_packages enable row level security; grant select on public.service_packages to anon,authenticated; grant update(price_fils) on public.service_packages to authenticated; create policy package_read on public.service_packages for select using (exists(select 1 from public.services s where s.id=service_id and s.active) or exists(select 1 from public.staff_roles r where r.user_id=auth.uid() and r.role='admin')); create policy package_admin on public.service_packages for update to authenticated using(exists(select 1 from public.staff_roles r where r.user_id=auth.uid() and r.role='admin')) with check(exists(select 1 from public.staff_roles r where r.user_id=auth.uid() and r.role='admin')); insert into public.service_packages select v.id,t.tier,t.price from (values ('cv',3000,5000),('wedding',7000,10000),('birthday',3000,5000),('card',5000,7000),('qr',2000,3000),('links',3000,5000),('certificate',3000,5000),('website',15000,25000),('menu',8000,12000),('catalog',8000,12000)) v(id,a,b) cross join lateral(values('advanced',v.a),('vip',v.b)) t(tier,price);